window.RP_SESSION={"id":"S-3e995ee32570","messages":[{"id":"RP-0216502","time":"2026-08-06T18:36:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"준비하시고-","characters":["P-6ba6a097816f"]},{"id":"RP-0216503","time":"2026-08-06T18:36:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"릴리즈!","characters":["P-6ba6a097816f"]},{"id":"RP-0216504","time":"2026-08-06T18:36:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-6ba6a097816f"]},{"id":"RP-0216505","time":"2026-08-06T18:36:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'올리브'의 민첩 판정 :\n[6] + [2] = [8]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0216506","time":"2026-08-06T18:36:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 텅!","characters":["P-6ba6a097816f"]},{"id":"RP-0216507","time":"2026-08-06T18:36:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 훈련장의 더미에 올리브의 화살이 정확하게 꽂힙니다!","characters":["P-6ba6a097816f"]},{"id":"RP-0216508","time":"2026-08-06T18:36:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"역시 나야!","characters":["P-6ba6a097816f"]},{"id":"RP-0216509","time":"2026-08-06T18:37:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"휘이이익...!","characters":["P-92738ae601c0"]},{"id":"RP-0216510","time":"2026-08-06T18:37:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-92738ae601c0"]},{"id":"RP-0216511","time":"2026-08-06T18:37:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 근데... 왜이렇게 덥담.","characters":["P-6ba6a097816f"]},{"id":"RP-0216512","time":"2026-08-06T18:37:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'머챈트 마이아'의 민첩 판정 :\n[10] + [1] = [11]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0216513","time":"2026-08-06T18:37:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"탕...!","characters":["P-92738ae601c0"]},{"id":"RP-0216514","time":"2026-08-06T18:38:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"오?\"","characters":["P-6ba6a097816f"]},{"id":"RP-0216515","time":"2026-08-06T18:38:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"올리브의 뒤에서 이제 막 활시위를 놓은 머챈트도 호기롭게 웃어보였습니다.\n\n\" 활 쏘기 좋은 날씨죠? 바람도 적고. \"","characters":["P-92738ae601c0"]},{"id":"RP-0216516","time":"2026-08-06T18:39:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"그렇네여!\"\n\n 올리브도 그런 머챈트를 향해 빵긋 웃습니다.","characters":["P-6ba6a097816f"]},{"id":"RP-0216517","time":"2026-08-06T18:39:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"그 덕분에 조금 더운건 싫긴 하지만, 좋은건 여전히 좋은게 아니겠슴까?!\"","characters":["P-6ba6a097816f"]},{"id":"RP-0216518","time":"2026-08-06T18:42:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"머챈트는 올리브의 옆으로 걸어오며 얘기 했습니다.\n\n\" 올리브씨죠? 얘기 들었어요. 이번에 낭랑한 활잡이가, \"\n\n화살을 활대에 놓고, 활시위를 당기며 고개를 휙!\n\n머리칼을 넘겼습니다.\n\n\" 들어왔다고 말예요. \"\n\n그리곤... 텅!\n\n다시 한 번 과녘에 머챈트의 화살이 꽂혔습니다.","characters":["P-92738ae601c0"]},{"id":"RP-0216519","time":"2026-08-06T18:45:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"어라? 어떻게 알고 계심까?\"\n\n 소갯말을 준비하던 올리브가 눈을 크게 뜹니다.\n\n \"히힛, 저 벌써 유명해진걸까여.\"\n\n 꺄르륵!","characters":["P-6ba6a097816f"]},{"id":"RP-0216520","time":"2026-08-06T18:46:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 사실 올리브가 이곳에 온지도 이제 일주일도 넘었으니 길드원이라면 알 사람은 알아야 할것.","characters":["P-6ba6a097816f"]},{"id":"RP-0216521","time":"2026-08-06T18:48:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 당연히 얘길 들었죠~ 길드에 사람이 새로 오고 갈 때마다 종종 얘길 하니까요.\n\n...아! 물론 가십거릴 뜯는단 얘긴 아녜요ㅋ. 어차피 한솥밥 먹게 될 사인데, 이름도 모르고 실수하는 것 보다얀... \"\n\n스으윽...\n\n\" 알고 만나는 편이 좋아서요...! \"\n\n텅...!","characters":["P-92738ae601c0"]},{"id":"RP-0216522","time":"2026-08-06T18:50:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"한솥밥 먹는 사임까.\"\n\n 올리브도 다시 더미로 시선을 돌려서...\n\n \"그거 좋군여!\"\n\n 텅!","characters":["P-6ba6a097816f"]},{"id":"RP-0216523","time":"2026-08-06T18:50:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"  \"그럼 선배님 성함이?\"","characters":["P-6ba6a097816f"]},{"id":"RP-0216524","time":"2026-08-06T18:53:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"머챈트는 다시금 활시위에 화살을 걸었습니다.\n\n턱까지 당겨진 활시위. \n\n\" 머챈트에요. 머챈트 마이아요. \" \n\n두 눈은 조용히 과녘을 향해있었습니다.\n\n과녘에 집중해서인지 아니면 쨍한 태양빛 때문인지. 미간에 옅게 인 주름도 오늘은 맑은 하늘 아래 빛을 내는 것 같았습니다.\n\n... 텅!","characters":["P-92738ae601c0"]},{"id":"RP-0216525","time":"2026-08-06T18:56:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 역시 조금은 바람이 불어주는게 좋으려나. 하지만 괜찮습니다. 올리브는 견디는 법을 잘 압니다.\n\n \"네! 머챈트 선배님!\"\n\n 올리브는 턱 밑의 깍지손을 놓았습니다.\n\n \"선배님도 궁수심까? 솜씨가 있으심다.\"","characters":["P-6ba6a097816f"]},{"id":"RP-0216526","time":"2026-08-06T19:01:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 아뇨, 전에 배웠어요. 길드에 윌리엄이란 친구가 있거든요. 지금은 멀리 멀리 쩌~~ 멀리 의뢰 한답시고 나가선 함흥차사지만...\n\n아! 길드에 올리브 말고도 활 다루는 걸 좋아하는 친구들이 많아요. 레마는 만나 보셨어요? \"","characters":["P-92738ae601c0"]},{"id":"RP-0216527","time":"2026-08-06T19:02:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"아! 네! 빨간 티플링 선배 말씀이시져?\"\n\n 그 분 말고는 만난적 없지만","characters":["P-6ba6a097816f"]},{"id":"RP-0216528","time":"2026-08-06T19:03:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"아, 선배님 오니라고 아심까? 레마 선배님과 같이 만나봤는데 팔이 네 개고 짱 큼다!\"","characters":["P-6ba6a097816f"]},{"id":"RP-0216529","time":"2026-08-06T19:03:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 어제 페트라를 본 것이 정말 인상 깊었다.","characters":["P-6ba6a097816f"]},{"id":"RP-0216530","time":"2026-08-06T19:04:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 네네, 레마나 엘타리온... 롯테... 미샤도 활을 쏘던가~? 무튼, 활을 다.... 어? \"","characters":["P-92738ae601c0"]},{"id":"RP-0216531","time":"2026-08-06T19:05:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"녱?\"","characters":["P-6ba6a097816f"]},{"id":"RP-0216532","time":"2026-08-06T19:05:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 생각해보니, 우리 길드에서 활 다루기 좋아하는 사람들은 대부분 여자였네요...! \"","characters":["P-92738ae601c0"]},{"id":"RP-0216533","time":"2026-08-06T19:05:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"그렇슴까?!\"","characters":["P-6ba6a097816f"]},{"id":"RP-0216534","time":"2026-08-06T19:06:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 허걱쓴","characters":["P-6ba6a097816f"]},{"id":"RP-0216535","time":"2026-08-06T19:07:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 화살에 뭐가 있는 걸까요? 퓽- \"\n\n머챈트는 빈 손으로 활 쏘는 시늉을 하며 잠시 웃었습니다.\n\n\" 몇살이에요? 앳되어 보이는데... 말 놔도 되죠? \"","characters":["P-92738ae601c0"]},{"id":"RP-0216536","time":"2026-08-06T19:08:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"올해로 스물셋임다!\"\n\n 어엿한 한 명의 으른이죠!","characters":["P-6ba6a097816f"]},{"id":"RP-0216537","time":"2026-08-06T19:09:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"선배님은여? 선배님은여? 근데 선배님이시니 저보다 어리셔도 말 놓으셔도 됨다!\"","characters":["P-6ba6a097816f"]},{"id":"RP-0216538","time":"2026-08-06T19:09:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 그래~? 왠지 풋풋하더라구. 이럴게 아니라, 다음에 활 쏘는 여자들끼리 한 번 모여 볼까? \"","characters":["P-92738ae601c0"]},{"id":"RP-0216539","time":"2026-08-06T19:10:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"세상에나 세상에나! 너무 좋슴다!\"\n\n 팔 붕붕","characters":["P-6ba6a097816f"]},{"id":"RP-0216540","time":"2026-08-06T19:13:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 좋아~! 간만의 걸스나잇을 한 번 즐겨보자구- \"\n\n머챈트는 싱긋 웃으며 다시금 과녘을 쳐다봤습니다.\n\n턱까지 당겨진 활시위.\n\n\" 그리고 내 나이는... \"\n\n새로운 친구와의 반가운 만남. 오늘의 활시위는 왜인지, 반짝이는 햇살 조차 당겨오는 것 같았습니다.\n\n\n그리고...\n\n\n\" ... 사랑하기 딱 좋은 나이...! \"\n\n\n...  텅!","characters":["P-92738ae601c0"]},{"id":"RP-0216541","time":"2026-08-06T19:13:00+09:00","room":"RP","name":"머챈트","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-92738ae601c0"]},{"id":"RP-0216542","time":"2026-08-06T19:13:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
